SELECT p.gender, CAST(p.anchor_age AS INT) AS age, s.admission_type_id, s.comorbitities, s.mechvent, s.vasopressors, s.rrt, CASE WHEN s.los <= 5 THEN 'LOS <= 5' WHEN s.los > 5 THEN 'LOS > 5' END AS los_category, COUNT(DISTINCT s.subject_id) AS patient_count, SUM(CASE WHEN s.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS death_count, AVG(s.los) AS avg_los FROM patients p JOIN admissions s ON p.subject_id = s.subject_id WHERE p.gender = 'M' AND CAST(p.anchor_age AS INT) BETWEEN 44 AND 54 AND s.admission_type_id IN (10028004, 10028005) GROUP BY p.gender, age, s.admission_type_id, s.comorbitities, s.mechvent, s.vasopressors, s.rrt, los_category;